-- Amplify totals counter (O18, REQ-37). Run once in the project's SQL editor.
-- Generated by tools/build_site.py from the portal's own screen list; do not edit by hand.
-- Stores totals only: one row per screen per UTC day. No IP address, no browser details, no identifier.

create table if not exists public.amp_daily (
  day date not null,
  screen text not null check (screen ~ '^[a-z0-9-]{1,24}$'),
  n integer not null default 0 check (n >= 0 and n <= 1000000),
  primary key (day, screen)
);
alter table public.amp_daily enable row level security;
revoke all on table public.amp_daily from public, anon, authenticated;

-- Add one to today's total for a known screen. Anything else is ignored.
create or replace function public.amp_count(s text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if s is null or not (s = any (array['hub', 'momentum', 'plan', 'coal', 'kit', 'pledge', 'radar', 'policy', 'map', 'acad', 'ysc', 'post', 'track', 'prof', 'incl', 'res', 'ai', 'brand', 'care', 'graph', 'corner', 'route', 'state', 'issues', 'guide', 'sources', 'latest', 'trust', 'health', 'changes', 'help', 'feedback', 'launch', 'about', 'home', 'media', 'communities', 'involve', 'ambassadors', 'campaign', 'learn', 'stem', 'research', 'service', 'golive', 'product', 'notify', 'parliament', 'civic', 'numbers'])) then return; end if;
  insert into public.amp_daily as d (day, screen, n) values ((now() at time zone 'utc')::date, s, 1)
  on conflict (day, screen) do update set n = least(d.n + 1, 1000000);
end; $$;

-- Totals for the last 1 to 90 days, newest first. Totals only: there is nothing else to read.
create or replace function public.amp_totals(days integer) returns table (day date, screen text, n integer)
language sql stable security definer set search_path = '' as $$
  select d.day, d.screen, d.n from public.amp_daily d
  where d.day > (now() at time zone 'utc')::date - least(greatest(coalesce(days, 28), 1), 90)
  order by d.day desc, d.n desc;
$$;

revoke all on function public.amp_count(text) from public;
revoke all on function public.amp_totals(integer) from public;
grant execute on function public.amp_count(text) to anon;
grant execute on function public.amp_totals(integer) to anon;
